/**
 * Operands that are bottom-up scope boundaries (sub-selects) are always hash-joined, because no correlated algorithm is
 * sound for them. With a build-row budget far below the build side the join spills the build overflow to disk and must
 * still produce exactly the bag SPARQL defines; the OPTIONAL-over-UNION path, which has a sound streaming fallback,
 * keeps using that fallback instead of spilling. Each case also runs without a budget, and the expected bags are
 * hand-computed.
 */
class HashJoinBuildBudgetQueryTest {

	private static final String MAX_BUILD_ROWS_PROPERTY = "org.eclipse.rdf4j.query.algebra.evaluation.hashjoin."
			+ "maxBuildRows";
	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final String PREFIX = "PREFIX : <urn:ex:>\n";

	private SailRepository repository;

	@BeforeEach
	void setUp() {
		repository = new SailRepository(new MemoryStore());
		repository.init();
		add(iri("a"), iri("p"), VF.createLiteral(1));
		add(iri("b"), iri("p"), VF.createLiteral(2));
		add(iri("c"), iri("p"), VF.createLiteral(3));
		add(iri("a"), iri("q"), VF.createLiteral(10));
		add(iri("a"), iri("q"), VF.createLiteral(11));
		add(iri("b"), iri("q"), VF.createLiteral(20));
		add(iri("d"), iri("q"), VF.createLiteral(40));
		add(iri("a"), iri("r"), VF.createLiteral(12));
	}

	@AfterEach
	void tearDown() {
		System.clearProperty(MAX_BUILD_ROWS_PROPERTY);
		repository.shutDown();
	}

	@ParameterizedTest(name = "maxBuildRows={0}")
	@ValueSource(strings = { "1", "0", "-1" })
	void optionalOverSubSelectWithSpilledBuildSide(String maxBuildRows) {
		System.setProperty(MAX_BUILD_ROWS_PROPERTY, maxBuildRows);
		String query = PREFIX + """
				SELECT ?s ?x ?v WHERE {
				  ?s :p ?x
				  OPTIONAL { SELECT ?s ?v WHERE { ?s :q ?v } }
				}
				""";
		assertThat(rows(query)).containsExactly(
				"{s=urn:ex:a, v=10, x=1}",
				"{s=urn:ex:a, v=11, x=1}",
				"{s=urn:ex:b, v=20, x=2}",
				"{s=urn:ex:c, x=3}");
	}

	@ParameterizedTest(name = "maxBuildRows={0}")
	@ValueSource(strings = { "1", "-1" })
	void optionalConditionOverSubSelectWithSpilledBuildSide(String maxBuildRows) {
		System.setProperty(MAX_BUILD_ROWS_PROPERTY, maxBuildRows);
		String query = PREFIX + """
				SELECT ?s ?x ?v WHERE {
				  ?s :p ?x
				  OPTIONAL { { SELECT ?s ?v WHERE { ?s :q ?v } } FILTER(?v > 10) }
				}
				""";
		assertThat(rows(query)).containsExactly(
				"{s=urn:ex:a, v=11, x=1}",
				"{s=urn:ex:b, v=20, x=2}",
				"{s=urn:ex:c, x=3}");
	}

	@ParameterizedTest(name = "maxBuildRows={0}")
	@ValueSource(strings = { "1", "-1" })
	void optionalConditionRejectingEverySpilledCandidateKeepsBareRows(String maxBuildRows) {
		System.setProperty(MAX_BUILD_ROWS_PROPERTY, maxBuildRows);
		String query = PREFIX + """
				SELECT ?s ?x ?v WHERE {
				  ?s :p ?x
				  OPTIONAL { { SELECT ?s ?v WHERE { ?s :q ?v } } FILTER(?v > 100) }
				}
				""";
		assertThat(rows(query)).containsExactly(
				"{s=urn:ex:a, x=1}",
				"{s=urn:ex:b, x=2}",
				"{s=urn:ex:c, x=3}");
	}

	@ParameterizedTest(name = "maxBuildRows={0}")
	@ValueSource(strings = { "1", "-1" })
	void joinWithSubSelectWithSpilledBuildSide(String maxBuildRows) {
		System.setProperty(MAX_BUILD_ROWS_PROPERTY, maxBuildRows);
		String query = PREFIX + """
				SELECT ?s ?x ?v WHERE {
				  ?s :p ?x
				  { SELECT ?s ?v WHERE { ?s :q ?v } }
				}
				""";
		assertThat(rows(query)).containsExactly(
				"{s=urn:ex:a, v=10, x=1}",
				"{s=urn:ex:a, v=11, x=1}",
				"{s=urn:ex:b, v=20, x=2}");
	}

	@ParameterizedTest(name = "maxBuildRows={0}")
	@ValueSource(strings = { "1", "-1" })
	void optionalOverUnionKeepsResultsUnderABuildBudget(String maxBuildRows) {
		System.setProperty(MAX_BUILD_ROWS_PROPERTY, maxBuildRows);
		String query = PREFIX + """
				SELECT ?s ?x ?y WHERE {
				  ?s :p ?x
				  OPTIONAL { { ?s :q ?y } UNION { ?s :r ?y } }
				}
				""";
		assertThat(rows(query)).containsExactly(
				"{s=urn:ex:a, x=1, y=10}",
				"{s=urn:ex:a, x=1, y=11}",
				"{s=urn:ex:a, x=1, y=12}",
				"{s=urn:ex:b, x=2, y=20}",
				"{s=urn:ex:c, x=3}");
	}

	private static IRI iri(String local) {
		return VF.createIRI("urn:ex:" + local);
	}

	private void add(IRI subject, IRI predicate, Value object) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.add(subject, predicate, object);
		}
	}

	private List<String> rows(String query) {
		List<String> rows = new ArrayList<>();
		try (SailRepositoryConnection connection = repository.getConnection();
				TupleQueryResult result = connection.prepareTupleQuery(query).evaluate()) {
			while (result.hasNext()) {
				BindingSet bindingSet = result.next();
				TreeMap<String, String> sorted = new TreeMap<>();
				for (String name : bindingSet.getBindingNames()) {
					Value value = bindingSet.getValue(name);
					if (value != null) {
						sorted.put(name, value.stringValue());
					}
				}
				rows.add(sorted.toString());
			}
		}
		rows.sort(Comparator.naturalOrder());
		return rows;
	}
}
